Here is the commit message:
Call term_mode_init() properly when DTE_FORCE_TERMINFO is set

This fixes a bug that was introduced in commit
23daf151dc4ba9d32eeb3c45a215ed44f8c5423d.

Here is the root cause:
The bug was caused by the improper placement of the `term_mode_init()` function call within the `term_init()` function. The call was originally located after the check for the `DTE_FORCE_TERMINFO` environment variable, which could lead to the terminal mode not being initialized correctly before other terminal initialization logic was executed. This could result in failures when trying to get terminal attributes, as the terminal mode would not be set up properly.

Here is the patch:

 void term_init(void)
 {
     const char *term = getenv("TERM");
     if (term == NULL || term[0] == '\0') {
         term_init_fail("'TERM' not set");
     }

+    if (!term_mode_init()) {
+        term_init_fail("tcgetattr: %s", strerror(errno));
+    }
+
     if (getenv("DTE_FORCE_TERMINFO")) {
         if (term_init_terminfo(term)) {
             return;
         } else {
             term_init_fail("'DTE_FORCE_TERMINFO' set but terminfo not linked");
         }
     }

-    if (!term_mode_init()) {
-        term_init_fail("tcgetattr: %s", strerror(errno));
-    }
-
     switch (get_term_type(term)) {
     case TERM_XTERM:
         terminal = xterm;
         // terminal.repeat_byte = &ecma48_repeat_byte;
         break;
     case TERM_ST:
     case TERM_URXVT:
         terminal = xterm;
         break;
     case TERM_TMUX:
     case TERM_SCREEN:
     case TERM_KITTY:
         terminal = xterm;
         terminal.back_color_erase = false;
         break;
     case TERM_LINUX:
         // Use the default Terminal and just change the control codes
         terminal.control_codes.hide_cursor = xterm.control_codes.hide_cursor;
         terminal.control_codes.show_cursor = xterm.control_codes.show_cursor;
         break;
     case TERM_OTHER:
         if (term_init_terminfo(term)) {
             return;
         }
         break;
     }

     const char *colorterm = getenv("COLORTERM");
     if (colorterm && streq(colorterm, "truecolor")) {
         terminal.color_type = TERM_TRUE_COLOR;
         return;
     }

     if (
         terminal.color_type < TERM_256_COLOR
         && str_has_suffix(term, "256color")
     ) {
         terminal.color_type = TERM_256_COLOR;
     } else if (str_has_suffix(term, "-direct")) {
         terminal.color_type = TERM_TRUE_COLOR;
     }
 }
